import {money,escapeHtml as e} from './shared.mjs';
import {careBoundary} from './offer-summary.mjs';
import {serviceCoverage} from './service-area.mjs';
import {guideReviewChoices} from './guide-practical-steps.mjs';
import {searchGuideAdditions} from './search-content.mjs';
import {p,a,link,section,richSection,ul,ol,box,worksheet,table,auditTable,download,sources,anchoredSection,disclosureSection,formatGuideSections} from './guide-content-helpers.mjs';

// Authoritative final section definitions, in reading order. Offer values are
// evaluated from the caller's current configuration on every render.
const guideContent={
 "/guides/website-maintenance-cost/":o=>[
  richSection('three-bills','Budget for three different jobs',p('Website maintenance cost depends on who operates the platform, who checks the customer journey and who makes changes. Start with three lines: provider bills, routine care and improvement work. A low hosting bill can be perfectly sensible, but it does not tell you whether anyone checks your form or updates your opening hours.')+ul(['Provider bills keep accounts and tools available: domain renewal, hosting, business email and any paid booking or newsletter service.','Routine care checks the website and makes small updates within a stated allowance. Ask who notices an outage and who follows it up.','Improvement work changes the content or experience: a clearer service page, an article or a better inquiry journey. Budget this separately when the care plan does not include it.'])+p('A static brochure site, a CMS with several editors and a store have different moving parts. Write down the actual tools before comparing monthly fees.')),
  section('platform-cost', 'Add provider bills to the work you need', `<p>Hosting, a domain, mailboxes and paid form or booking tools are separate from maintenance work. Check the actual plan, billing term and renewal price with each provider. Free tiers have limits; a published subscription price does not include someone checking or updating your site.</p><p>The plan comparison below covers optional studio work. An existing site needs the one-time Website Baseline if no current, usable review exists. A site you can maintain yourself may need no monthly studio service.</p>`),
  richSection('studio-plans','What the studio’s monthly plans pay for',auditTable('Wonder and Method monthly plans — USD',['Plan','Monthly price','Work included'],[
   ['Keep Running',money(o.plans.keep_running.monthly_price),'Availability and certificate monitoring; monthly site, form and known-workflow checks; basic search-health checks; one group of supplied updates; quarterly status review and a dated report.'],
   ['Improve',money(o.plans.improve.monthly_price),'Keep Running plus monthly keyword research, one complete improvement, quarterly topic-map refresh and a 20-minute review or written equivalent.'],
   ['Grow',money(o.plans.grow.monthly_price),'Keep Running plus deeper keyword/competitor research, a rolling 90-day plan, two connected improvements, one small promotional item made from approved content and a 30-minute review or written equivalent.']
  ])+p('These are studio service fees. You own and pay for hosting, domains and paid tools directly. Monthly service is optional. Each monthly improvement is one agreed finished task, such as rewriting a service page. See '+a('/services/website-care/','the full plan scope')+' and '+a('/pricing/','billing choices and terms')+'.')),
  richSection('first-year','Work out the first-year service budget',p(`For an eligible existing site with no usable baseline, twelve monthly Keep Running cycles would total ${money(o.plans.keep_running.monthly_price*12)}. Add the ${money(o.baseline.one_time_price)} one-time baseline and the studio-service total is ${money(o.plans.keep_running.monthly_price*12+o.baseline.one_time_price)}, before provider bills and applicable taxes. This example uses monthly billing for twelve cycles, not annual prepayment.`)+p('A current, usable review from a paid studio build or Audit &amp; Fix Sprint can satisfy the Website Baseline requirement; the same review is not charged again. Work bundled into a build is not resold as an overlapping monthly task. Start recurring service when there is distinct work to do.')+download('maintenance-budget','Download the maintenance budget worksheet')+p('List the renewal date, billing owner, cost, included work and evidence of the last check. A list of subscriptions is not a maintenance record.')),
  richSection('checks','Ask what gets checked and how recovery works',ul(['Does the public domain load over HTTPS, and is the certificate valid? Record the date and the person who follows up on an alert.','Can a permitted test inquiry be submitted, found at its receiving destination and replied to? A green form message alone is not enough.','Which CMS, plugins and external tools need updates, and who tests the affected pages afterward? A static site may have a different update process.','What is backed up: files, content, database and settings? Can an authorized person restore a copy away from the live site?','Who owns Search Console, domain recovery and vendor billing? Check access before the only administrator leaves.'])+p(`${a(sources.backups,'WordPress’s backup guidance')} distinguishes database and file backups. Other platforms have different export and recovery limits; confirm yours. A successful export is useful evidence, but a recovery test establishes whether the site can actually be restored.`)+careBoundary()),
  richSection('choose-care','Choose the help you need',p('If the site works and you can own its checks, you may only need provider subscriptions and occasional help. If small updates and routine checks are repeatedly missed, care may fit. Choose an improvement plan when you have content or customer-journey work ready to approve; choose a finite review when the cause of a problem is still unclear.'))
 ],
 "/guides/website-launch-checklist/":o=>[
  anchoredSection(['launch-check-tools'],richSection('release-record','Start with one version and one decision maker',p('A launch checklist should answer a practical question: can a customer use this version, and can the owner operate it afterward? Name the preview version, public domain, approver and launch window. Keep a short list of unresolved issues with an owner for each. “Looks good” is not a record of what was checked.')+p('Use four result labels: pass, fail, not applicable and blocked. A check that needs an unavailable account is blocked, not passed. Keep preview access and search visibility intentional until the owner approves the public release.')+download('launch-checklist','Download the website launch checklist'))),
  richSection('content-approval','Approve the facts customers act on',ul(['Read the main service page aloud. Can a new visitor tell what is offered, where it is available and how to start?','Verify prices, opening hours, service boundaries and response expectations with the business owner.','Check project images, testimonials and credentials against permission and actual evidence. Remove placeholders.','Open policy links and downloads. Confirm the contact details and the person responsible for inquiries.','Confirm image descriptions convey relevant meaning and decorative images do not repeat surrounding text.'])+p('For a contractor, a project photo needs an accurate description of the work shown. For a consultant, the inquiry should ask for the information needed to assess fit. The check is about this business, not filling every available section of a template.')),
  section('customer-journey','Check forms and connected tools','<p>Follow the <a href="/guides/contact-form-not-working/">contact-form test</a> from submission to reply. Open booking and other connected tools on a phone. Confirm the right person receives requests and knows what to do next.</p>'),
  section('accounts-search','Your accounts and the developer’s launch checks','<p>Confirm that you can access the domain, hosting and included tools, and that recovery contacts are current. Keep control of these accounts throughout the project.</p><details><summary>Checks for your developer</summary><p>Verify HTTPS, preferred domain, titles, descriptions, canonical URLs, sitemap, indexing instructions, redirects and the missing-page response. Keep private previews out of search. Preserve unrelated email DNS settings. Record Search Console access and inspect the intended public URLs after launch; a live test does not guarantee indexing.</p></details>'),
  richSection('recovery','Know how to recover before the switch',p('Keep the approved source, content and configuration needed to restore the prior version. Name the person who can perform the rollback and the condition that would trigger it, such as a broken inquiry path. Check what the host can restore and what lives in a separate service. Do not assume a website backup also contains mailbox, booking or newsletter data.')+p('A launch record should name the deployed version, time, checks and unresolved items. On a redesign, attach the '+a('/guides/website-migration-checklist/','old-to-new URL map')+'.')),
  section('live-check','Recheck the live site','<p>Open the public website outside the preview session. Check the main pages, a useful old URL, a download and a missing URL. Repeat the <a href="/guides/contact-form-not-working/">form test</a>. Record the result and who will handle any remaining issue. For a replacement website, keep the <a href="/guides/website-migration-checklist/">migration checklist</a> with your launch notes.</p>')
 ],
 "/guides/ai-website-or-custom/":o=>[
  richSection('choose-the-job','Start with the work the website must do',p('An AI website builder can help turn a short brief into a first draft of a layout and copy. A custom project can put more attention into the service story, visual direction and connected customer journey. Either can be a reasonable starting point. Neither removes the need to check the facts, test the form and decide who maintains the result.')+p('“AI” describes a tool or method; “custom” describes how closely the work is shaped around your requirements. They can overlap. A designer may use AI during a custom project, and an owner may refine a builder draft with expert help. Compare the finished responsibilities and handoff.')),
  richSection('comparison','Compare the same brief in each approach',auditTable('Questions for an AI builder and a custom project',['Decision','Builder-led approach','Custom project'],[
   ['Content','Who corrects generated service claims, prices and location details?','Who interviews the owner, drafts the pages and obtains factual approval?'],
   ['Design','Can the editor support the layout and brand changes you need?','Which original design decisions are included, and how many review rounds?'],
   ['Functions','Does the selected plan support the real form, booking or store task?','Which connections are configured and tested within the signed scope?'],
   ['Editing','Can the owner make a routine change without breaking the layout?','Is editing through a CMS, technical source or a maintenance service?'],
   ['Ownership','What can be exported, and what requires the platform to keep running?','Which paid source and assets are handed over, and which licenses remain?'],
   ['Cost','What are the subscription, renewal, add-on and usage costs?','What are the build fee, provider bills and optional ongoing work?']
  ])+p('A subscription comparison is not a total project comparison. Include the owner’s time for writing, media selection, checking and ongoing edits. Use the '+a('/guides/website-project-cost/','website cost guide')+' to put both options on the same basis.')),
  section('trial', 'Test the generated draft before buying more work', `<p>Try a short, factual brief: “Create a draft website for a Buffalo garden-care business. Use these approved services and coverage details. Leave missing prices, credentials and project examples blank. Make the main action a request for an estimate.” Supply only information you have permission to use.</p>${ol(['Check whether the tool invented a review, qualification, address or completed project. Remove each unsupported claim.', 'Replace a service paragraph and one image. Check the phone layout and whether you can undo the change.', 'Test the full form with a controlled address, then inspect where the message arrived and whether you can reply.', 'Ask what can be exported, how backups work and which features stop when the subscription ends.'])}<p>Use ${link('/assets/downloads/audit-website-approach.csv', 'the approach comparison worksheet')} to record the results. If the design structure itself is the question, use ${link('/guides/custom-website-or-template/', 'the separate custom-versus-template guide')}.</p>`),
  richSection('review-ai-copy','Review generated copy like any other draft',p('Check every service claim against the business’s actual work. Look for invented years of experience, credentials, client names, project results and locations. Replace vague claims with specific approved facts: what you do, what you need from a customer and what happens after an inquiry.')+p(`Google’s ${a(sources.aiContent,'guidance on generative AI content')} allows room for AI as a research and structuring aid, while emphasizing accurate, relevant content and warning against producing many pages without value for users. Publishing the same generic page under many town names does not answer a new customer question.`)+p('Keep a named human approver for business claims. A generated project image should not be presented as a photograph of completed customer work. Review licenses and the tool’s actual terms for the assets you intend to publish.')),
  richSection('ai-search','Being built with AI does not buy AI-search visibility',p(`Google says its ${a(sources.aiSearch,'AI Overviews and AI Mode guidance')} follows the same core search practices: make the site accessible to crawling, provide helpful content, and meet the requirements for eligible pages. It does not require special AI markup or an extra machine-readable AI file to appear in those features. Inclusion is not guaranteed.`)+p('The practical task is still to explain the real service, support claims, use clear internal links and keep the information current. Ask any provider selling an AI-search service what they will change and what evidence they can report. A builder’s AI label is not evidence of visibility.')),
  richSection('custom-fit','When a studio project is worth discussing',p(`Wonder and Method’s Launch package is ${money(o.launch_site.public_price)} for up to ${o.launch_site.marketing_page_cap} marketing pages; Focused is ${money(o.focused_site.public_price)} for up to ${o.focused_site.marketing_page_cap}; Signature is ${money(o.signature_site.public_price)} for up to ${o.signature_site.marketing_page_cap}. Page counts are scope limits. Editing, connected tools and creative needs should drive the choice. Read the ${a('/pricing/','complete package inclusions')} before comparing a quote.`))
 ],
 "/guides/website-not-showing-on-google/":o=>[
  richSection('intent','First confirm that the page should be public',p('Ask the site owner whether this version is ready for search. A preview, unfinished offer, private client page or deliberately held launch should not be made discoverable simply to clear an audit flag. Record who can approve a visibility change and which exact routes that approval covers.')+p('For a page approved for search, ask the maintainer to check access and indexing instructions on the actual public address, including response headers. Google’s '+a('https://developers.google.com/search/docs/essentials/technical','technical requirements')+' distinguish a working, accessible page with indexable content from a guarantee of indexing. Blocking crawling and instructing a search engine not to index are different controls; changing either needs an intentional decision.')),
  richSection('discovery','Check discovery and the current page',p('Can a visitor reach the page through a relevant link on the website? Does the link open the intended address and useful content, rather than an error, login or abandoned preview? Ask the maintainer to check the response and any redirects. For a replacement website, compare the old address with the agreed new destination.')+ul(['Record the canonical public address you intend people to use.','Find a normal internal link to that page and follow it.','Check whether a recent launch, address change or access change explains the timing.','If a migration is involved, compare the old-to-new URL map before changing more addresses.'])+p('A sitemap can help communicate intended URLs, but it does not replace useful navigation or prove that a page is indexed. Use the '+a('/guides/website-migration-checklist/','migration checklist')+' when useful old pages have moved.')),
  section('inspection-steps', 'Run your first Search Console check', "<span id=\"index\"></span><p>Google Search Console is Google’s free tool for checking how it sees your website. A <code>site:yourdomain.com</code> search can provide a clue, but missing results do not prove the page is unindexed. If you lack Search Console access, ask the domain owner or web person to add you or send the exact page’s URL Inspection result.</p>"+(ol([
      'Open the property for the correct domain in Search Console. Paste the complete public page URL into the inspection bar and press Enter.',
      'Read the indexing result and the last crawl information. Open the explanation if Google says the URL is not indexed; note the reason before changing the page.',
      'Choose Test live URL to check the current version. Compare it with the indexed result: a recent correction may not be reflected in the older crawl.',
      'If the public page is eligible and the problem has been fixed, use Request indexing. Check the sitemap and useful internal links too; repeated requests do not guarantee a place in search.'
    ]) + '<p>See ' + link('https://support.google.com/webmasters/answer/9012289', 'Google’s URL Inspection instructions') + '.</p>')),
  richSection('define','Describe what is missing',p('“My website is not showing on Google” can describe several different problems. Perhaps a new page has never appeared, an older page disappeared after a redesign, a service search shows other businesses, or the business is absent from Maps. Each needs different evidence. Buying more pages before identifying the problem can leave the original issue untouched.')+p('Write down the exact page address, search phrase, date and result you expected. Include whether you searched for the business name, a service or a location. A single search is a starting observation, not a complete performance report. If a customer sent a screenshot, ask which query produced it rather than guessing from the image.')+worksheet('google-visibility-flow','Download the search-visibility worksheet')),
  richSection('relevance','Separate being indexed from answering a search',p('When the page is available for search but does not appear for the query you care about, review the question itself. Does the page clearly explain the relevant service, who it serves, delivery boundaries and the next step? Does it provide useful facts a prospective customer needs, or mostly general promises?')+p('Review available Search Console queries and pages over a stated period. Distinguish impressions, clicks and actual inquiries. Agree one improvement and record when it was made; avoid treating a simultaneous redesign, price change and content rewrite as proof that one sentence caused a result. The '+a('/guides/seo-work-and-reporting/','SEO reporting guide')+' explains what a useful work record contains.')),
  richSection('maps','Treat Maps as a separate question',p('A missing business profile is not the same as a missing website page. Check the business’s actual operating model and '+a('/guides/local-seo-profile-eligibility/','Google Business Profile eligibility')+' before proposing profile work. Do not invent a storefront or office to make the business look local. Online service reach can be explained honestly on the website.')+p('Finish with a written next step: retain an intentional hold, resolve a confirmed access problem, inspect an indexing explanation, improve a relevant page or investigate eligible profile details. '+a('/services/seo/','SEO research and implementation')+' can address an agreed website task; a broader '+a('/services/website-audit/','website audit')+' can help when search, content and inquiry problems overlap. Neither establishes a guaranteed ranking or timetable.')),
  richSection('specific-index-checks','Use the reported reason to choose the next check',auditTable('Search Console findings and next checks',['Finding','What to check next'],[
   ['Excluded by noindex','Confirm this public page is approved for search. Then inspect both the HTML robots directive and X-Robots-Tag response header.'],
   ['Blocked by robots.txt','Review the rule affecting this exact path. Crawling restrictions and noindex do different jobs; do not remove a deliberate private/preview policy.'],
   ['Page with redirect or another canonical','Follow the destination and compare it with the intended URL map. Inspect the selected canonical separately.'],
   ['Not found or server error','Open the URL, check the HTTP response and review hosting/application errors. Fix a wrong internal link or an unintended failure.'],
   ['Discovered — currently not indexed','Google knows the address but has not crawled it. Check internal links and server availability; this status alone does not identify a content defect.'],
   ['Crawled — currently not indexed','Google fetched the page but has not indexed it. Review whether it adds something new or mostly repeats another page. Repeated submission is not a remedy.']
  ])+p(`These checks follow Google’s ${a(sources.indexing,'Page indexing report documentation')}. Use ${a(sources.inspection,'URL Inspection')} for the exact page, compare the recorded crawl with a live test and keep the evidence date. A live pass cannot guarantee indexing.`)+p('If the page is indexed but a service search does not show it, examine the query and page in Search Console’s Performance report. That is a relevance and visibility question, not proof of a broken sitemap. Google Analytics 4 can help assess visits when correctly configured; it cannot establish Google’s indexing decision.')),
  section('plain-search-terms','A few search terms in plain language','<p><strong>Indexing:</strong> Google has stored a page that may appear in results. <strong>Ranking:</strong> where a result appears for a particular search. <strong>Canonical:</strong> the preferred address when similar pages exist. <strong>Noindex:</strong> an instruction asking search engines not to include a page. Ask your developer before removing it from a private or unfinished page.</p>')
 ],
 "/guides/contact-form-not-working/":o=>[
  section('five-minute-check','Start with a five-minute owner check',"<span id=\"trace\"></span><span id=\"inbox\"></span>"+(ol(['Open the public form on your phone and send one clearly labeled test using an email address you control. Note the time and confirmation.','Search the receiving inbox, spam and quarantine for that test. Confirm that someone checks this mailbox.','Open the form settings and check the notification recipient. An old employee or former provider may still be listed.','If your platform keeps submissions, look for the same test there. Some WordPress plugins and custom forms do not save a separate copy.','Reply to the test from the business mailbox. If any step fails, give your web person the page, time and observed result; keep passwords and customer records private.']))+"<p><a href=\"/assets/guides/contact-form-flow-worksheet.txt\">Download the contact-form test checklist (TXT)</a>.</p>"),
  section('platform-settings', 'Check the notification destination in your platform', `<p><strong>Squarespace:</strong> edit the page, open the form block and check <strong>Email Notifications</strong>. Select the displayed email address to review the destination. Changing the account email does not update an existing form’s recipient. Trial sites cannot send form emails unless the owner is a Squarespace Circle member. Repeat one labeled test after correcting the destination. ${link('https://support.squarespace.com/hc/en-us/articles/205814638-Set-up-form-and-newsletter-storage', 'Squarespace’s form notification and storage instructions')}.</p><p><strong>Wix:</strong> inspect the notification automation for the exact form. For the current form workflow, open <strong>More Actions → Edit → Send an email → Show additional settings → Recipients → Edit</strong>, then choose <strong>Apply</strong>. The site owner is the default recipient; collaborator access and older form versions can differ. Account email, business email and ownership changes do not automatically update existing automation recipients. Check those recipients directly, find the test in the submissions table and test again. ${link('https://support.wix.com/en/article/wix-forms-choosing-who-gets-notified-about-form-submissions', 'Wix’s notification instructions')} and ${link('https://support.wix.com/en/article/the-new-automation-builder-troubleshooting-wix-automations', 'automation troubleshooting')}.</p><p><strong>WordPress:</strong> identify the form plugin first, then inspect that form’s notification recipient and any mail-service log. Plugin settings differ. Give support the plugin name and the failed stage; do not install a second mail plugin without checking the current setup.</p><p>A saved submission and an email notification are separate results. These checks help identify a problem; support for your platform and any paid repair still need a fit review.</p>`),
  section('review-options','Choose a review or a supported small fix',p(`Repair an existing included form under its applicable agreement before buying another. When you need a genuinely separate simple contact form, the ${a('/services/website-addons/#addon-contact_form','additional contact-form scope')} is ${money(o.add_ons.find(item=>item.id==='contact_form').public_price)}, with up to six fields and one destination.`)+`<p>The ${link('/contact/?offer=website_baseline&amp;goal=fix&amp;request_kind=question#inquiry',money(o.baseline.one_time_price)+' Website Baseline')} reviews the site, sets priorities and includes one small first fix if safe and practical. The ${link('/contact/?offer=audit_fix_sprint&amp;goal=fix&amp;request_kind=question#inquiry',money(o.audit_sprint.one_time_price)+' Audit &amp; Fix Sprint')} includes the Baseline and up to two agreed small fixes in total. Both cover one supported site with up to ${o.baseline.page_cap} marketing pages. Platform, access and fit are checked first. ${link('/services/website-audit/','Compare the full review scopes')}.</p>`),
  richSection('page','Check what the visitor can do',p('Open the public page on a phone as well as the device where the problem was reported. Can you reach every field, understand what is required and activate the submit button? Submit a deliberately incomplete test first, then correct it. Validation should explain the missing information without erasing everything already typed.')+ul(['Check required fields, email format and the visible error message.','Record whether a loading state finishes or stays stuck.','Check whether the confirmation refers to this submission or is just always-visible page text.','Capture the wording and time of the result without including private customer information.'])+p('If the page fails before submission, ask the maintainer to investigate that reproducible step. Changing mailbox settings would not explain a button that never sends a request. Where the problem affects the wider page, use the '+a('/guides/website-repair-or-redesign/','repair-or-redesign decision guide')+' before assuming a complete rebuild is necessary.')),
  richSection('verify','Retest the customer task and keep the record',p('After the agreed correction, repeat the submission-to-reply test and record the result at each step. Check another relevant device if the original issue involved mobile use. Mark any unresolved access or provider dependency explicitly. Remove test records according to the business’s approved retention practice.')+p('A useful finish is a dated record of the problem, the smallest supported change, the test and the remaining limitation. It is not merely a screenshot of a green success message. The '+a('/guides/website-audit-checklist/','website audit checklist')+' helps connect this check with the wider customer journey.')),
  disclosureSection('specific-form-checks','For your web person: trace the failed step','Receiving-system, email-delivery and technical checks',[
   richSection('receipt','Confirm that the receiving system accepted it',p('Ask the authorized operator to look for the same test in the system that receives inquiries. Depending on the setup, that evidence might be a stored record, submission identifier or provider receipt. A site may not store a separate inquiry record; document the actual design instead of assuming that every form has a database.')+p('If the browser reports success but the operator cannot establish receipt, capture both observations. Ask the maintainer to check the submission response and the agreed receiving destination. Do not paste passwords, access tokens, full logs or customer records into a public support conversation. Request a redacted finding and a clear next action.')+p('Illustrative example: the test appears in a permitted submission record, but no notification is found. That narrows the investigation to the later delivery stages. It does not prove the form lost the inquiry or that a different website platform is required.')),
   richSection('notification','Check the notification attempt',p('Once receipt is established, find out whether the system attempted to notify the intended business address. Confirm the destination spelling and whether an old employee, former provider or test mailbox still receives the messages. Review the notification status through authorized tools if those tools provide one.')+p('Distinguish a notification being requested from it being accepted by an email service, and distinguish both from arrival in the reader’s inbox. Record the actual status shown, rather than translating an unfamiliar provider label into “delivered.” If the service reports rejection or a delay, give that exact redacted finding to the responsible maintainer.')+p('The next technical check depends on the system in use. Sender configuration, allowed destinations, service limits or an expired connection may warrant investigation, but this checklist cannot identify one of them without evidence. Make one agreed change, keep a recovery route and repeat the same test.')),
   richSection('specific-form-checks','Match the symptom to a concrete check',auditTable('Contact-form symptoms, checks and next actions',['Symptom','Check','Next action'],[
   ['Submit does nothing','Check visible field errors and whether the CAPTCHA loads. Try a fresh session on the actual public domain.','Record browser, URL and time. Ask the maintainer to inspect script/network errors and the configured challenge hostname.'],
   ['Challenge keeps failing','Record the displayed error code; a changed hostname or expired challenge can require different action.','Use the provider’s error guidance. Do not disable spam protection to make a test pass.'],
   ['Success appears, but no inquiry is found','Check the form provider’s submission record and the server response, using authorized access.','Confirm whether it was stored before investigating email. A success message can be misleading if the application handles errors incorrectly.'],
   ['Record saved, email missing','Check the current destination, notification log, sender settings, quotas and any expired email connection.','Correct the evidenced failure and repeat the same labeled test. On WordPress, identify the configured mail path before adding an SMTP plugin.'],
   ['Email goes to spam or bounces','Inspect the redacted rejection reason and sender authentication result.','Ask your mail administrator to check SPF, DKIM and DMARC: domain settings that help receiving mail services verify who sent a message. Do not change these records yourself without qualified help.'],
   ['Reply goes to the wrong address','Inspect the controlled test message’s Reply-To value.','Use the verified business sender for From and the validated customer address for Reply-To where supported; retest the reply.']
  ])+p(`For Turnstile, ${a(sources.challenge,'Cloudflare’s error-code reference')} distinguishes invalid configuration, unauthorized hostnames and expired challenges. ${a(sources.email,'Google’s email sender guidelines')} explain authentication requirements for mail sent to Gmail. An authentication pass can help delivery, but does not prove inbox arrival.`)+p('Give support the URL, time, test reference, failed stage and redacted error. Keep passwords, tokens and customer records out of the report.'))
  ])
 ],
 "/guides/service-area-pages/":o=>[
  richSection('question','Begin with a customer decision',p('A service-area page should help someone decide whether and how a business can serve them. A place name alone does not answer that question. Before writing, identify the useful decision: availability at an address, remote versus on-site delivery, the relevant service, or information needed for a quote.')+p('Separate a coverage list from a landing-page plan. A list can reassure a visitor that their community is within the intended area. It does not automatically justify a new page for each place. For a small service business, one clear service page and an accurate coverage explanation may answer more questions than many nearly identical pages.')+worksheet('service-area-decision','Download the service-area planning worksheet')),
  richSection('facts','Confirm what your business actually does',p('Write down your services, how you deliver them and the places you actually cover before drafting a local page. Record whether work happens online, at the customer’s property or at a genuine business location. Identify any address-level assessment, travel charge or scheduling condition that customers need to understand; leave unknown conditions unresolved until the business supplies them.')+ul(['Which of your services are available here, and which are not?','What should a customer send you to request a quote?','Is there a genuine local difference that changes the decision?','Who will update your pages when coverage changes?'])+p('Do not convert service reach into an office claim. A business can explain remote delivery to customers in a place without saying it has premises there. Business Profile eligibility is a separate question covered in the '+a('/guides/local-seo-profile-eligibility/','local SEO and profile guide')+'.')),
  richSection('choose','Choose the smallest useful page structure',p('Use an existing service page when the customer needs the same explanation wherever they live. Add a coverage section when the main distinction is whether an area is served. Consider a separate page when a visitor has a distinct question and the business can supply substantive facts that answer it. There is no useful minimum city count or required number of location pages.')+p('For example, an established service may have different booking requirements in a particular area. If those requirements are real, meaningful and maintained, they may warrant a separate explanation. A paragraph about a landmark, a stock photograph and the same contact button do not establish a different customer task.')+p('Google’s '+a('https://developers.google.com/search/docs/essentials/spam-policies','search spam policies')+' describe doorway abuse and keyword stuffing, including pages or city blocks created to manipulate search visibility. The practical editorial decision here is to consolidate overlapping questions and keep local statements useful to customers.')),
  richSection('example','Work through an illustrative example',p('Imagine a fictional exterior-cleaning business that serves several nearby communities. Its actual quote process requires photographs, the surface type and access details. If those requirements are the same everywhere, one cleaning-service page can explain them and link to a coverage section. Repeating that page with a different town heading adds little to the quote decision.')+p('Now suppose the owner supplies a verified difference: one service is offered only within a smaller route area on stated days. The useful addition is a clear explanation of that service’s actual availability and how a customer checks their address. It may fit as a section on the service page. A separate page is an option only if there is enough distinct information to help the visitor.')+p('This is a fictional planning example, not a studio client, service recommendation or statement about local operating conditions. Any real business must supply its own coverage and booking facts.')),
  richSection('build','Write the page around the next action',p('Start with the service and the audience. Explain delivery, relevant boundaries, what the customer needs to provide and what happens next. Use actual evidence where available: an approved explanation of the process or a genuine, permissioned project. If no local project evidence exists, describe the process plainly instead of inventing a case study.')+p('Connect the page to the main service, pricing or quote explanation and a relevant contact step. A reader should be able to move between the detailed service and its coverage without starting again from the homepage. Use descriptive links that explain the destination; repeating a service-and-city phrase in every link does not make the route easier to understand.')+p('For a new site, agree these page purposes in the '+a('/guides/website-redesign-brief/','website brief')+'. For an existing site with overlapping local pages, inventory their useful content and URLs before consolidating anything; the '+a('/guides/website-migration-checklist/','migration checklist')+' explains why redirect decisions need a plan.')+p(`Only when a distinct new page is useful and exceeds your included allowance, an ${a('/services/website-addons/#addon-standard_page','additional standard page')} is ${money(o.add_ons.find(item=>item.id==='standard_page').public_price)}. The ${money(o.add_ons.find(item=>item.id==='three_page_bundle').public_price)} three-page bundle covers three related additional pages; it is not a reason to publish near-identical town pages.`)),
  richSection('maintain','Keep the coverage honest and current',p(e(serviceCoverage().statement)+' The '+a('/areas/erie-county/','Erie County coverage page')+' gives more detail about the studio’s home county. Its community names do not claim offices, local client relationships or a different package in each place. That is a deliberate fit between the page and the studio’s delivery model.')+p('Review your own coverage when services, staffing or booking conditions change. Record the owner’s confirmation and the pages affected. Use available search and inquiry information to find unanswered customer questions, rather than treating every keyword variation as a publishing instruction.')+p('The next step may be one better service section, a clearer county page or a genuinely distinct new page. '+a('/services/seo/','SEO research and implemented website improvements')+' can help decide which change is useful. Measure what happens after the work, and keep outcomes separate from the fact that a page was published.'))
 ],
 "/guides/website-maintenance-checklist/":o=>[
  section('start','Write down what you need to keep working',p('Website maintenance is a recurring responsibility, not a promise that nothing will ever go wrong. Start with the tasks that matter to the business: explain the current service, let a visitor contact or book, deliver that request to the right place and give the owner a recoverable way to operate the site. A site that loads can still fail one of those tasks.')+p('Write down the platform, domain, hosting, forms, booking provider and any connected tools. Name who owns each account and who can approve changes. Keep credentials in an appropriate password manager or access system; the downloadable log is for tasks and evidence, not passwords or private customer data.')+p(`Use the ${a('/assets/guides/website-maintenance-log.csv','website maintenance log')} to record a check, its owner, observed result, next action and retest. The cadence below is a planning example, not a universal service commitment.`)),
  section('schedule','Use a schedule that matches the actual website',`<div class="journal-table-wrap" role="region" tabindex="0" aria-label="Suggested website maintenance schedule"><table><caption>A suggested starting schedule to adapt</caption><thead><tr><th scope="col">When</th><th scope="col">What to check</th><th scope="col">What to record</th></tr></thead><tbody><tr><th scope="row">After an approved change</th><td>The changed page or tool, nearby navigation and its main visitor task.</td><td>The exact change, affected URLs, observed result and recovery option.</td></tr><tr><th scope="row">Monthly or at an agreed interval</th><td>Important pages on a phone, contact and booking paths, current service details and available alerts.</td><td>Which tasks were checked, which were not and the person responsible for any follow-up.</td></tr><tr><th scope="row">Quarterly or after a material business change</th><td>Account ownership, access, recovery arrangements, outdated content and outstanding issues.</td><td>Access gaps, upcoming renewals, recovery evidence and the next agreed priority.</td></tr><tr><th scope="row">Before a renewal or seasonal change</th><td>Domain and provider renewal details, dates, availability and any expiring offering.</td><td>Who confirms the renewal or content change and its due date.</td></tr></tbody></table></div>`+p('A store, booking business or frequently updated CMS may need a different cadence and specialist support. Agree the interval and response coverage explicitly. Automated availability checks can help surface a problem, but they do not prove that a customer can complete the whole journey.')),
  section('forms','Test the contact route','<p>Follow a service page to the contact form or booking tool on your phone. Send one labeled test, check where it arrives and reply from the business mailbox. A success message alone does not prove delivery. Use the <a href="/guides/contact-form-not-working/">full form troubleshooting guide</a> if a step fails.</p>'),
  section('content','Review the facts a customer relies on',ul(['Are services, service areas, hours and contact routes still accurate?','Do prices, inclusions and booking requirements agree across the site?','Do links and downloads reach the intended current destination?','Can a phone visitor read the content and reach the next step without a layout problem?','Do expired events, offers or staff details need a clear update?','Can the responsible editor make an approved change without breaking the page?'])+p('Make a small, coherent list of corrections. List the changes you are supplying, the affected pages and how they will be checked. New services, a major rewrite or a new application may require a separately scoped project rather than being treated as routine upkeep.')),
  section('recovery','Arrange updates, backups and recovery separately',careBoundary()+'<p>Agree technical updates and emergency recovery separately with your host or a qualified developer. Before a major change, that person should identify the previous working version and explain how it can be restored. Ask what has actually been tested; an export file alone does not prove recovery works.</p>'),
  section('receipt','Keep a simple maintenance log','<p>Record the date, page or tool, what happened, the change made and who will handle anything left to do. Use the <a href="/assets/guides/website-maintenance-log.csv">maintenance log (CSV)</a> and compare <a href="/services/website-care/">care plan coverage</a> if you want help with regular checks.</p>')
 ],
 "/guides/contractor-website-checklist/":o=>[
  section('job','Tell customers which jobs you take',p('A contractor website should help a visitor decide whether the business does the work they need, serves their location and has a sensible way to assess the request. More traffic does not resolve an unclear offer or an inquiry form the team cannot use. Start with those decisions before adding pages or choosing an SEO campaign.')+p('List your trades or services, the jobs you accept, the jobs you turn down and how a customer starts. A business taking planned remodeling projects should not accidentally imply emergency repairs. A firm accepting commercial work should explain that distinction rather than relying on a photograph to communicate it.')+p(`The ${a('/assets/guides/contractor-website-worksheet.csv','contractor website worksheet')} connects each service with evidence, coverage, inquiry fields and a completion check. Use it to prepare a real brief; the example row is fictional.`)),
  section('services','Give each service a useful answer',p('A service page earns its place when a customer needs a distinct explanation. Describe the work included, suitable projects, dependencies and what happens before a quote or appointment. Closely related words can often share one page when they describe the same service and decision.')+ul(['Name the work in language customers use and the team can support.','Explain what information is needed to assess a request.','Identify any site visit, consultation or review required before pricing.','Use approved process details instead of promises about speed or availability.','Link related services and the actual inquiry route.'])+p('A county or town name is useful when it clarifies coverage. Repeating the same service copy across many town pages adds little for the visitor. Create a distinct location page only when there is substantial, accurate information that belongs there.')),
  section('evidence','Show real work with permission',p('Project photographs and short explanations can help a customer understand the work. Obtain the necessary permission and rights, identify what the business actually did and remove private customer details. A concise example can name the problem, scope, constraints and completed work without inventing a performance result.')+p('Keep professional credentials, insurance statements, memberships and reviews accurate and current. Publish them only when the business has supplied and approved the supporting facts. Do not create testimonials or imply that an illustrative design is a completed customer project.')+p('For a new business without suitable project examples, use a clear service explanation and an honest process. A labeled illustration can explain how work is planned, but it should remain visibly distinct from evidence of completed jobs.')),
  section('coverage','Explain where and how you work',p('State the real service territory and how location affects the next step. If work depends on job type, travel distance or scheduling, explain what the team needs to confirm. The website should distinguish an office address, a travel area and online communication rather than treating them as interchangeable.')+p('For a New York business covering several towns or counties, a navigable coverage section can answer the first location question. Municipal names sometimes overlap; use enough context to avoid confusion. Niagara Falls, New York and Niagara Falls, Ontario, for example, are different locations.')+p(`Our ${a('/areas/','county service guides')} show one way to organize regional information. Your business needs its own accurate coverage and evidence. See the ${a('/guides/service-area-pages/','service-area page guide')} for the decision about when another page is useful.`)),
  section('inquiry','Ask for the information needed to respond',p(`If a separate request path needs conditional questions, the ${a('/services/website-addons/#addon-guided_quote_form','guided quote-request form')} is ${money(o.add_ons.find(item=>item.id==='guided_quote_form').public_price)} for its listed scope. It gathers details for a human quote and does not calculate job prices. Your included simple forms remain included.`)+p('Choose form fields with the person who handles requests. Useful starting points may include the service, job location, short scope description, preferred contact method and desired timing. Ask only for information the team needs at this stage, and explain any next review or response expectation accurately.')+p('An estimate request is not a confirmed price, accepted job or appointment. The confirmation should say what happened and what the customer should expect next. If the system retains submissions, the owner needs access to the saved record; notification delivery is checked separately.')+p('Photo uploads, custom quoting, dispatch and customer portals can add complexity and privacy responsibilities. Include them only after defining the actual workflow, supported provider, access, storage and costs. They are not automatically part of a simple marketing website.')+p(`Walk through the complete request on a phone and confirm the receiving side. If it fails, use the ${a('/guides/contact-form-not-working/','form troubleshooting guide')} before spending more to attract visitors.`)),
  section('search','Use SEO to improve an already useful path',p('Keyword research can reveal how people describe a service or a question before buying. Check the location, intent and current search results before deciding what to create. A reported low or zero search volume is a limited estimate, while an unavailable metric means the tool returned no measurement; neither replaces knowledge of real customer questions.')+p('Map relevant terms to useful service pages, coverage information or a substantive guide. Then review headings, internal links, indexability and the visitor’s next step. Track what was changed and use available search and inquiry evidence over a suitable period, without attributing every fluctuation to one edit.')+p(`At Wonder and Method, ${a('/services/contractor-websites/','contractor website design')} starts with an agreed scope; ${a('/services/seo/','SEO work')} adds defined research and implemented improvements. Use the ${a('/assets/guides/contractor-website-worksheet.csv','worksheet')} to outline the services, approved proof and inquiry process, then ${a('/contact/','discuss the project')}.`))
 ],
 "/guides/website-project-cost/":o=>[
  section('start-with-scope', 'Compare the same work in each quote', `<p>Write one page list, feature list and editing requirement before comparing proposals. Check who prepares the writing and images, connects tools, moves old URLs and publishes the finished site. The prices below are Wonder and Method’s published scopes, not a Buffalo market average.</p>`),
  section('dated-price-example', 'Three fixed website scopes', table('Current studio website prices', ['Offer', 'Fixed build fee', 'Marketing-page allowance'], ['launch_site', 'focused_site', 'signature_site'].map(id => [link('/pricing/#offer-' + id, o[id].public_name), money(o[id].public_price), `Up to ${o[id].marketing_page_cap} pages; provider bills separate.`])) + '<p>For a DIY comparison, enter the actual subscription, domain, paid tools and time required to write, build and check the site. Confirm the current plan at the provider before choosing. A subscription price alone is not a finished website budget.</p>'),
  section('two-budgets','What each build includes',p('Every studio website package includes writing, keyword research, on-site SEO, design, two combined feedback rounds, checks before launch, source files and a written handoff. You control the accounts. One initial launch and 30 days of correction for defects against the accepted scope are included.')+p('Launch supports a clear presence with one form and one ready service connection. Focused adds more service detail, two forms, two original guides and up to two ready connections. Signature adds a larger page plan, four original guides and an original animated hero or 3D centerpiece. Guides count within the page allowance; these are scope caps, not targets to fill.')+p(`See ${a('/pricing/#website-packages','the complete package comparison')} for creative assets, handoff and feature limits.`)),
  section('optional-additions','Budget only for genuinely additional work',table('Examples of one-time website add-ons',['Additional work','Studio fee','Scope'],['standard_page','three_page_bundle','campaign_landing_page','contact_form','guided_quote_form'].map(id=>{const item=o.add_ons.find(addon=>addon.id===id);return [a('/services/website-addons/#addon-'+item.id,item.public_name),money(item.public_price),e(item.summary)];}))+p('Use included page slots, forms and ready service connections first. The same page or form is never charged twice. A campaign landing page is its own additional page; it does not also need a standard-page charge. Each listed selection covers one unit or bundle, with any further quantity agreed in writing.')+p(`For example, one additional standard page and one additional contact form add ${money(o.add_ons.find(item=>item.id==='standard_page').public_price+o.add_ons.find(item=>item.id==='contact_form').public_price)} to studio fees when both are genuinely beyond your included scope. Provider fees and applicable tax remain separate. See ${a('/services/website-addons/','all twelve add-ons and their limits')} for booking, payments, CRM, reporting, store and custom-tool options.`)),
  section('ongoing-costs','Separate the build from the bills that continue',p(`Optional monthly plans are Keep Running ${money(o.plans.keep_running.monthly_price)}, Improve ${money(o.plans.improve.monthly_price)} and Grow ${money(o.plans.grow.monthly_price)}. Hosting, domain, mailbox and form/email charges are paid directly to approved providers. Other services require separate scope and approved costs. One agreed initial website launch is included; monthly service is optional.`)+box('Worked example — assumed costs, not a provider quote',p(`Focused ${money(o.focused_site.public_price)} plus 12 Keep Running invoices at ${money(o.plans.keep_running.monthly_price)} has ${money(o.focused_site.public_price+12*o.plans.keep_running.monthly_price)} of studio service fees. Assume monthly service runs for 12 months from launch, hosting is $20/month for 12 months and all other provider charges total $120. Add $240 hosting and $120 other fees once. Estimated total: ${money(o.focused_site.public_price+12*o.plans.keep_running.monthly_price+240+120)}, before taxes or added scope. These assumed fees must be replaced with actual approved bills.`))+p('Required provider fees are confirmed before you commit. Monthly work must be distinct from launch scope and defect correction; the same work is never charged twice.')+p(`An eligible existing site needs a ${money(o.baseline.one_time_price)} Website Baseline only if no current, usable review exists. A studio build or ${money(o.audit_sprint.one_time_price)} Sprint can satisfy that requirement when its review still covers the site. Monthly service is optional, not financed website ownership; builds use 50/30/20 written-acceptance milestones.`)),
  section('annual-choice', 'Check the payment schedule', `<p>Website payments are 50% at booking, 30% at written design acceptance and 20% at written staging acceptance. For Launch, that is ${money(o.launch_site.public_price*.5)}, ${money(o.launch_site.public_price*.3)} and ${money(o.launch_site.public_price*.2)}. Domain, hosting and paid tools are separate. See ${link('/pricing/#payments','payment and cancellation terms')}.</p>`),
  section('scope-changers','What changes the budget?',ul(['Additional features or connections beyond the accepted page and feature list.','A large migration, original field research or facts that must be established.','Original photography, full identity redesign or creative production beyond the listed assets.','Additional review rounds, a new direction or extra marketing pages.'])+p('Useful copy for the agreed purposes has no word quota. One initial website launch and the agreed ready-service connections are included. Extra work receives a written scope and price before it begins.')),
  section('compare-quotes','Bring the same brief to each conversation',p('Ask each studio to respond to the same list of pages, supplied content, required features, editing needs, review dates and acceptance checks. Then compare what is included, what is excluded and how a change is priced. Timeline should follow actual inputs and review capacity; a vague rush request is not a reliable schedule.')+box('Before requesting a quote',ul(['Name one customer action the site should make easier.','List the pages and features you actually need.','Identify the content owner and one approver.','Choose an editing approach and record outside bills.','Ask what you receive at handoff and what happens after launch.']))+p(`Use the ${a('/guides/website-redesign-brief/','redesign brief')} to prepare, explore ${a('/services/web-design/','custom web design in Buffalo')}, or ${a('/contact/','send the project details')}.`))
 ],
 "/guides/website-redesign-brief/":o=>[
  section('before-a-redesign','First, confirm that a redesign is the right job',p(`If you have not yet decided what needs to change, ${a('/guides/website-repair-or-redesign/','compare keeping, fixing, reworking and rebuilding the site')}. This brief helps define a redesign after that earlier decision.`)),
  section('decision','Begin with the decision your customer is making',p('“We need a modern website” is a starting feeling, not yet a project brief. A useful brief says who the website is for, what they need to understand and what they should do next. That gives the design a purpose and makes proposals easier to compare.')+p('For a Buffalo or Erie County service business, the next step might be an estimate request, a phone conversation or a project inquiry. Choose a primary action. Explain what a qualified inquiry looks like so that a form can collect useful details without becoming a long application.')),
  section('business','1. Describe the actual business',ul(['What do you sell, and which one or two service lines matter most?','Who is a good fit, and who is outside the scope?','Where do you deliver the service? Distinguish online work, customer visits and a staffed location.','What should a visitor know before contacting you?','Which claims, qualifications and examples can you support?'])+p('Be specific about geography. Serving customers in Amherst or Hamburg does not imply a public office there. If the business works online, say so. Accurate service information is more useful than a list of town names pasted into every paragraph.')),
  section('content','2. Inventory the content before redesigning it',p('List the current URLs, page titles and purpose of each page. Mark what should remain, what needs rewriting and what can be retired. Identify pages that receive valuable inquiries or search visits before merging them.')+p('Collect approved service facts, the jobs you accept, actual delivery areas, contact and opening details, licensed photographs, and evidence you have permission to share. Add recurring customer questions, mark missing material and name the person responsible for approving changes and keeping each fact current. For a seasonal service, for example, the estimate may depend on property type, the actual route and information needed before booking; the business supplies its own operating facts.')+p(`If URLs will change, use the ${a('/guides/website-migration-checklist/','migration checklist')} to map each useful old address to the most relevant new destination.`)),
  section('editing','3. Decide who edits and what the site must do',p('Describe updates in everyday terms: “I change opening hours twice a year,” “our team publishes weekly,” or “prices come from another system.” Those are different requirements. A custom static website may fit infrequent changes; all three website packages include editable source code and instructions. Agree who will make, check and publish changes, and how often help will be needed.')+ul(['Does the site need only an inquiry form, or does it need booking or payment?','Will people sign in or view private information?','Does data move into a CRM or another service?','Who maintains integrations and pays the provider bills?','What happens if an external service is unavailable?'])+p('Write required features separately from ideas that would be nice later. That protects the initial project from quietly becoming a different product.')),
  section('acceptance','4. Define how the project gets approved',p('Name one approver, input dates and realistic review windows. Agree which pages and forms must work on a phone and with a keyboard. Ask the developer to record how the previous version can be restored. Capture changes in one consolidated list so decisions do not conflict across messages.')+p('Before launch, approval should identify the actual version and destination. After launch, handoff should include paid source, assets and licenses, account ownership, provider renewals, form-data handling and recovery notes. Wonder and Method includes 30 calendar days of correction for defects against accepted scope; later monthly care or SEO work is optional.')+box('A brief you can reuse',p(`${a('/assets/downloads/website-redesign-brief.txt','Download the plain-text redesign brief')} and fill it in with your own business facts. It opens in any text editor and can be pasted into a document.`))+p(`Read the ${a('/assets/audit-implementation/illustrative-completed-brief.txt','completed illustrative brief')}—a fictional planning example, not a client project. See ${a('/process/','the studio process')}, compare ${a('/services/web-design/','website scopes')}, then ${a('/contact/','start a conversation')}.`))
 ],
 "/guides/local-seo-profile-eligibility/":o=>[
  section('two-surfaces','Your website and your Business Profile have different jobs',p('Local SEO helps a business explain what it offers and where it serves customers. Your website can give that explanation in detail. A Google Business Profile is a separate product with its own eligibility rules. Having a website or serving Buffalo customers does not by itself make a business eligible for a profile.')+p('Google says local results consider relevance, distance and prominence. Useful website work can make services clearer, but it cannot remove the distance between a searcher and a business. No page edit can promise a particular Maps position. See '+a('https://support.google.com/business/answer/7091','Google’s explanation of local ranking')+'.')),
  section('eligibility','Check eligibility before choosing an address',p('Google generally requires eligible businesses to make in-person contact with customers during their stated hours. Online-only businesses are not eligible for a Business Profile. A service-area business that visits customers may qualify under the applicable rules; a studio delivering all work remotely should not assume that it does. Read '+a('https://support.google.com/business/answer/3038177','Google’s business representation guidelines')+' and its '+a('https://support.google.com/business/answer/13763036','eligibility guidance')+'.')+p('For an eligible business that travels to customers and does not serve them at its address, Google instructs it to hide that address. Service areas should describe actual service, not a collection of desirable search locations. Confirm your situation against '+a('https://support.google.com/business/answer/9157481','Google’s service-area instructions')+' before changing the profile.')+box('How I describe my own studio',p(e(serviceCoverage().statement)+' Our coverage describes online service reach; it does not claim a walk-in office or in-person service. We do not use a virtual-office address to imply otherwise.'))),
  section('pages','Write pages around the services people need',p('Begin with a clear page for each materially different primary service. Explain the customer problem, what is included, what changes the price, where the work is delivered and how to inquire. A redesign prospect and an ongoing SEO prospect have different questions, so they deserve clear paths.')+p('For a Buffalo-area service firm, local detail can be practical: travel boundaries, remote review options, appointment requirements or the information needed for a quote. Use only facts that apply. Copying one page into dozens of town-name variants adds little if the service and evidence are identical.')+p('A useful Erie County service-area page can gather coverage and working arrangements. A separate town page needs a separate reason to exist: genuinely different logistics, service details or supported work examples. A new place name alone is not that reason.')),
  section('sequence','A practical order for local search work',ul(['Verify the business name, contact details, service model and profile eligibility.','Make the primary service pages clear, complete and easy to reach.','Fix broken inquiry paths and misleading location information.','Link useful planning guides to the relevant service, pricing and contact pages.','Measure page-level search visibility and actual inquiry quality before choosing more work.'])),
  section('expectations','Buy a defined improvement, then evaluate it',p('Ask what will change on the website, why that is the next priority and how completion will be checked. “More SEO” is too broad to evaluate. A clearer service explanation, repaired internal link and verified inquiry path are concrete work; their commercial effect still needs measurement.')+p(`Explore ${a('/services/seo/','scoped SEO services for Buffalo businesses')}, read our ${a('/areas/erie-county/','Erie County delivery model')}, or ${a('/contact/','discuss the next useful improvement')}.`)),
  section('local-profile-actions', 'Local search steps for a trade business', ol([
      'Start with actual coverage: list the towns and jobs the team serves, what requires a site visit, and how an estimate is arranged.',
      'If the business qualifies for a Google Business Profile, use its real business name and the fewest specific categories that describe its core work. A business that visits customers and does not receive them at its address should hide that address.',
      'Keep the business name, controlled phone number, website link and customer-facing hours consistent across the website and the profiles you maintain.',
      'After real work, invite customers to leave an honest review through the profile’s review link. Offer no reward or discount for a review, and reply without revealing customer details.',
      'Build one useful page per distinct service. Add approved project photos, the job types accepted, real coverage and a working estimate request before making more town pages.'
    ]) + `<p>Check ${link('https://support.google.com/business/answer/3038177', 'Google’s business representation rules')} and ${link('https://support.google.com/business/answer/3474122', 'review guidance')}. These steps help people assess and contact the business; they do not promise a ranking.</p>`)
 ],
 "/guides/seo-work-and-reporting/":o=>[
  section('work','A monthly report should connect work to a decision',p('A list of rankings does not tell you what an SEO service actually did. Useful reporting connects a customer problem, a specific page change, the checks performed and the next decision. Search measurements add context, but they should not replace an inspectable work record.')+p('For a small Buffalo service business, the priority may be modest and valuable: explain a service boundary, improve a confusing inquiry step or make an important page easier to find. A monthly purchase should name the unit of work so both sides can tell when it is complete.')),
  section('keyword-opportunities','How keyword opportunities become useful work',p('Start with the real service, the customer question and the action you want a useful page to support. Keyword research can help identify related searches, difficulty estimates and competing content. Search Console and actual customer questions add evidence about the website and business. Record what is available and label what is missing.')+ul(['Investigate relevant lower-competition terms, existing pages with useful impressions, customer questions and seasonal opportunities.','Check actual search results: are people looking for a service, guide, product, map listing or comparison?','Compare competing pages and identify a truthful useful contribution your business can make.','Group close variants around the same need; improve an existing page when it already fits.','Select the page or action, record why it matters and define what finished work will include.'])+p('Keyword difficulty and search volume are estimates, not ranking probabilities or deadlines. Record the metric source, lookup date and geography; national organic difficulty is not a neighborhood map-ranking estimate. A low score for an irrelevant term is not a good business opportunity.')+p('Your opportunity brief should identify the customer question, business fit, available metrics, result-page observations, preferred URL, approved facts and completion test. '+a('/assets/guides/monthly-seo-opportunity-worksheet.csv','Download the monthly opportunity worksheet')+'. No invented keyword figures are supplied in the example.')),
  section('receipt','What a useful monthly report shows',box('Example only — no client outcome claimed',ul(['Property: an illustrative local service website. Role: website and content implementation. Period: one monthly work cycle.','Problem: visitors cannot tell whether they need a new site or an improvement to an existing one.','Change: revise the existing service page with a clearer fit explanation and one primary inquiry action.','Related fix: add a descriptive internal link from the pricing page.','Checks: compare claims with the accepted scope; test links, keyboard use, mobile layout and form validation.','Measurement: record the implementation date and compare relevant page and inquiry data when available. No uplift is assumed.','Next decision: keep the change, refine an unresolved question or stop if no useful scoped task remains.']))+p('The report should link to the changed page or clearly identify the section. It should also name anything still waiting for access or a decision. If analytics access is missing, the report should say so instead of presenting guessed results.')+p(`For an actual owned example, inspect ${a('/assets/buyer-packs/owned-audit-two-fixes','the dated audit-and-two-fix packet')}. To choose the task before interpreting its report, use ${a('/guides/website-care-versus-seo/','the care-versus-SEO comparison')}.`)),
  section('metrics','Read search data in context',p('Search Console reports clicks; impressions (how often a result was shown); click-through rate (the share of those impressions that led to a click); and average position (the average result position). Filter by the page, query, country, device and period relevant to the question. A site-wide average can hide what happened to one service page. Google explains these measures in its '+a('https://support.google.com/webmasters/answer/7576553','Performance report documentation')+'.')+p('A comparison also needs context: the dates, what changed, whether the sample is small and whether seasonality or other activity could explain the difference. A few additional clicks do not establish that one edit caused growth. Keep observations separate from interpretations.')+p('Qualified inquiries add another view. Record whether the person needs the service you offer, is within the delivery scope and can move toward a real conversation. Avoid putting names, email addresses or message contents into a public SEO report.')+p(`If you need a shared reporting view, the ${a('/services/website-addons/#addon-reporting_dashboard','website reporting dashboard')} is a one-time ${money(o.add_ons.find(item=>item.id==='reporting_dashboard').public_price)} setup for up to two existing sources and eight agreed metrics. This does not replace the work report already included in monthly service. New tracking infrastructure and ongoing analysis need separate scope.`)),
  section('scope','Choose the amount of work you can use',p(`Keep Running at ${money(o.plans.keep_running.monthly_price)}/month covers agreed checks and a related batch of updates using supplied content. Improve at ${money(o.plans.improve.monthly_price)}/month adds a monthly keyword opportunity brief, ${o.plans.improve.priorities} complete improvement${o.plans.improve.priorities===1?'':'s'} and quarterly topic-map refresh. Grow at ${money(o.plans.grow.monthly_price)}/month includes the same care, deeper keyword/competitor research and ${o.plans.grow.priorities} connected improvements in total, instead of Improve’s one. It also includes a rolling 90-day plan and one small promotional reuse task.`)+p(`For example, Improve could rewrite a service page from approved facts, including relevant metadata, internal links, publication and contact-path checks. Grow could pair that page with a distinct buyer guide. The separate promotional item uses that approved content; its limits are below. Agree useful work before the cycle starts. ${a('/services/website-care/','Read the plan limits and coverage')} and ${a('/pricing/#payments','payment and cancellation terms')}.`)),
  section('campaigns','Plan the next useful work',p('A rolling 90-day plan connects this month’s work with the next customer questions to answer. Update it when services or evidence change; it is a planning horizon, not a promise of search results.')+p('Grow also includes one small piece made from approved content: a simple graphic in up to three sizes with a caption, or a newsletter excerpt up to 150 words. This is additional to its two main improvements. Public posting or sending needs explicit approval; a new creative concept or email setup needs separate scope.')),
  section('time','How long should you wait?',p('Implementation can have a clear completion date; search impact does not have a guaranteed date. Start with a baseline and a measurement window suited to the available volume. If the site is new, unindexed or receives very little relevant traffic, a short comparison may not support a meaningful conclusion.')+p('Ask the provider to explain uncertainty and the next action. A good decision may be to collect more data, improve a different customer question or stop recurring work until a useful task is available. Promises of guaranteed Google positions or guaranteed AI citations should not substitute for a defined service.')+p(`Read ${a('/services/seo/','the full SEO scope')}, compare ${a('/pricing/','current pricing')}, inspect ${a('/work/','the studio work')}, or ${a('/contact/','discuss your existing website')}.`))
 ],
 "/guides/website-migration-checklist/":o=>[
  section('inventory','Treat a redesign as a move when addresses change',p('A new website can look finished while important old links lead nowhere. If page addresses, domains, content structure or hosting change, plan the move alongside the design. The aim is to preserve useful paths for customers and give search engines clear signals about the new locations. No checklist can guarantee that traffic stays unchanged.')+p('Begin with an inventory of current URLs, downloads, forms and external integrations. Identify the pages that receive meaningful search visits, customer inquiries or links. Keep a recoverable copy of the existing site and a record of who controls the domain, hosting and email settings.')),
  section('map','Build an old-to-new URL map',p('For each important old URL, record the most relevant new destination and the reason for the decision. Keep an address unchanged when that serves the new structure. If content is combined, map the old page to the new page that answers the same need. Do not send every retired service or article to the home page.')+p('Google recommends mapping URLs and implementing appropriate permanent redirects for a site move. It also describes temporary search fluctuations while a move is processed. Use its '+a('https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes','site-move documentation')+' for the technical details.')+box('Make the mapping explicit',p(`${a('/assets/downloads/website-url-map.csv','Download the URL map worksheet (CSV)')}. It starts with three example rows you can replace. Record the old URL, new URL, decision, reason, person responsible and what to check. These are invented examples, not a client migration.`))),
  section('redirect-example', 'A URL map you can hand to your developer', table('Illustrative migration map', ['Old URL', 'New URL', 'Action'], [
      ['/lawn-care', '/services/lawn-care/', 'Permanent redirect to the matching service page.'],
      ['/about/', '/about/', 'Keep the address; no redirect needed.'],
      ['/spring-2023-offer/', 'No replacement', 'Remove obsolete internal links and return 404 or 410 if no equivalent page exists.']
    ]) + `<p>Have the developer check that each redirect reaches the final page in one step. Google recommends keeping redirects for as long as possible, generally at least a year. For a move to a different domain or subdomain, review Search Console’s Change of Address procedure as well. A same-domain path change is a different case. ${link('https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes', 'Google’s site-move guidance')}.</p>`),
  section('before','Before launch: checks for you and your developer','<h3>Your checks</h3>'+ol(['Approve the new service details, photos, contact information and page list.','Open the main pages on a phone; check navigation, downloads and booking links.','Use the <a href="/guides/contact-form-not-working/">form test</a> to confirm a request reaches the business.'])+'<details><summary>Developer checks before switching the live site</summary>'+ol(['Check permanent redirects, page titles, canonical URLs, sitemap and indexing settings. Keep private previews out of search.','Record the approved release, destination and way to restore the previous version.','Name the exact DNS changes. Preserve unrelated email records and confirm the mailbox still works.','Test keyboard access, narrow layouts and connected services.'])+'</details>'),
  section('launch','Recheck the live website','<p>After the switch, open the public home, service and contact pages, a useful old link, a download and a missing address. Ask the developer to confirm redirects and missing-page responses. Repeat the contact-form test on the live site and record anything not yet verified.</p>'),
  section('after','Review the move over time',p('After an intentionally indexable launch, use the available search tools to review crawling, indexing and page-level performance. Compare the same kinds of traffic over useful periods and investigate patterns instead of reacting to one day. If indexing is still paused, do not interpret the absence of rankings as a content result.')+p('A migration can range from a few renamed pages to a major platform move. Extensive migration, WordPress remediation and new integrations are separately scoped work; this guide does not promise a universal rescue service.')+p(`Prepare with the ${a('/guides/website-redesign-brief/','redesign brief')}, explore ${a('/services/web-design/','website design')}, review ${a('/services/seo/','SEO improvements')}, or ${a('/contact/','discuss the actual move')}.`)),
  section('redesign-help','Plan the move with the redesign','<p>Use the URL map when discussing a <a href="/services/website-redesign/">website redesign</a>. The proposal should name retained pages, redirects, account access, email responsibilities and the launch checks.</p>')
 ],
 "/guides/custom-website-or-template/":o=>[
  section('fit','Both approaches can work. Fit is the question.',p('A template offers an existing visual and structural starting point. A custom website can organize the experience around the business’s particular story and customer journey. Neither label tells you, by itself, whether a site is clear, fast, accessible or easy to maintain.')+p('For a Buffalo small business choosing a website, begin with content and operations. What must customers understand? How often will the site change? Who will edit it? What can you invest in the build and in maintaining it? Those answers matter more than how many effects appear in a demo.')),
  section('compare','Compare the same customer journey',`<div class="journal-table-wrap" role="region" tabindex="0" aria-label="Questions to ask of either approach"><table><caption>Questions to ask of either approach</caption><thead><tr><th scope="col">Decision</th><th scope="col">Template starting point</th><th scope="col">Custom direction</th></tr></thead><tbody><tr><th scope="row">Service story</th><td>Does the existing page structure fit your content?</td><td>Can a tailored structure explain the service more clearly?</td></tr><tr><th scope="row">Editing</th><td>Which changes does the included editor support?</td><td>Does the owner need a developer or a separately included page editor to make changes?</td></tr><tr><th scope="row">Distinctive design</th><td>How much can be changed without fragile overrides?</td><td>Which original design decisions matter to the customer?</td></tr><tr><th scope="row">Ongoing cost</th><td>What subscriptions, add-ons and platform limits apply?</td><td>What hosting, provider and maintenance costs remain?</td></tr><tr><th scope="row">Handoff</th><td>What can you export or move to another provider?</td><td>Which paid source, assets and operating notes do you receive?</td></tr></tbody></table></div>`+p('Try a small comparison before committing: use the same service headline, explanation, proof and inquiry fields in each proposed structure. Walk through it on a phone. Notice where the content feels forced, where the next step disappears and which changes require workarounds.')),
  section('template','When a template may be a sensible starting point',p('A template may fit when the service is straightforward, the existing layout supports the content and the team values a familiar editing environment. It can reduce some initial design decisions. Still check the actual plan limits, recurring costs, access controls and export options.')+p('Do not assume that buying a template includes content strategy, copy, photography, migration, form delivery or accessibility review. Those responsibilities exist even when the layout is already drawn. Agree who completes and verifies them.')),
  section('custom','When custom work is useful',p('Custom work may fit when your service story, design or inquiry process needs a structure that a template cannot easily support. Agree what will be designed and built before choosing a package.')+p(`Studio builds are ${money(o.launch_site.public_price)}, ${money(o.focused_site.public_price)} and ${money(o.signature_site.public_price)} for up to 6, 15 and 30 marketing pages. Each includes writing, design, launch and source files. Future changes require coding skills, a developer or optional care; there is no built-in drag-and-drop editor. ${a('/pricing/#website-packages','Compare the full packages')} and tell me how often you need to edit.`)),
  section('quality','Judge the finished experience',ul(['Can a new visitor explain what the business does and who it serves?','Is the primary next step easy to find and complete on a phone?','Can the main journey be used with a keyboard and reduced motion?','Are prices or scope boundaries understandable?','Does the form accept the inquiry and can the owner find it and reply?','Can the owner maintain the site and recover it when needed?'])+p('A useful website explains the offer and lets people complete the next step. Motion can add character when it supports that job; it should pause cleanly and respect reduced-motion preferences.')+p(`Explore ${a('/work/','studio work and explorations')}, read ${a('/services/web-design/','the custom website scope')}, compare ${a('/guides/website-project-cost/','website budget examples')}, or ${a('/contact/','talk through the fit')}.`)),
  ...searchGuideAdditions('/guides/custom-website-or-template/')
 ],
 "/guides/website-care-versus-seo/":o=>[
  section('short-answer','Start with the problem, not the subscription',p('Website care keeps an agreed website and its existing tools dependable: correct supplied details, check important paths and record unresolved issues. Search work asks whether the right page answers a useful customer question, then improves that answer and checks what changed. A broken contact link can affect both, but it is still one correction.')+p('Neither label tells you how much implementation is included. Ask which site, systems, tasks and checks the agreement covers. A supported website with occasional updates may need care; a site with a specific content gap may need a finite improvement or a plan with an agreed search priority. A retainer is optional.')),
  section('compare','Compare tasks you can inspect',`<div class="journal-table-wrap" role="region" tabindex="0" aria-label="Different starting points, one clear work record"><table><caption>Different starting points, one clear work record</caption><thead><tr><th scope="col">Question</th><th scope="col">Care task</th><th scope="col">Search or content task</th></tr></thead><tbody><tr><th scope="row">Are the details correct?</th><td>Publish approved hours, contact details or links in existing components.</td><td>Check whether the service explanation answers the intended customer question.</td></tr><tr><th scope="row">What is being checked?</th><td>The covered site, form and known workflow, with dates and access limits.</td><td>The selected page, intent, factual copy and relevant search evidence when available.</td></tr><tr><th scope="row">What marks completion?</th><td>The agreed correction works, affected paths are checked and unresolved issues are recorded.</td><td>The approved page change and links are verified. Traffic or inquiry effects remain a separate observation.</td></tr><tr><th scope="row">What is not implied?</th><td>Unlimited changes, unsupported-system repair or continuous human monitoring.</td><td>Unlimited articles, link quotas, rankings or AI-search inclusion.</td></tr></tbody></table></div>`),
  section('situations','Three situations, three useful next steps',box('Illustration: changed contact hours',p('A business supplies a new schedule. Update the agreed contact section and related links as one small-change batch, inspect the phone layout and record the approved wording. This is a maintenance task; calling it an SEO campaign adds no useful definition.'))+box('Illustration: an unclear service page',p('A visitor cannot tell which repairs a business handles. Agree the page, approved service boundaries and next action. Revise that explanation, check the links and layout, then decide what actual page or inquiry evidence to observe. This may use one complete content improvement; a ranking increase is not a completion test.'))+box('Illustration: the problem is still unclear',p(`If you do not yet know what is failing, a finite ${a('/services/website-audit/','audit and agreed fixes')} can establish a baseline and finish a small agreed correction. It need not become a subscription. Use the ${a('/guides/website-audit-checklist/','audit checklist')} to describe the problem before choosing.`))),
  section('owned-change','Keep a simple record',p('For each month, write down the problem, the agreed change, the affected page, what was tested and what remains to do. Keep actual search or inquiry results separate from the fact that work was completed.')+p(`Use the ${a('/assets/guides/website-care-versus-seo-worksheet.csv','care-or-SEO decision worksheet (CSV)')} to choose the work you need. Keep the ${a('/assets/audit-implementation/work-receipt-template.txt','blank work-record template (TXT)')} with the completed checks.`)),
  section('plans','Compare the monthly options',p(`Keep Running is ${money(o.plans.keep_running.monthly_price)}/month for checks and one group of supplied updates. Improve is ${money(o.plans.improve.monthly_price)}/month for that care plus research and ${o.plans.improve.priorities} complete improvement${o.plans.improve.priorities===1?'':'s'}. Grow is ${money(o.plans.grow.monthly_price)}/month for care, deeper research, ${o.plans.grow.priorities} connected improvements and one small item made from approved content.`)+p(`An improvement can be a service page, guide or another agreed task; it does not always mean a new page. Compare the ${a('/services/website-care/','full allowances and exclusions')}. If no useful work is agreed, the next invoice pauses. Historic prepaid rights are described in ${a('/payments/#annual-terms','the payment terms')}.`)),
  section('costs','Check setup and ongoing costs',p(`Monthly service is optional; an eligible existing site needs the ${money(o.baseline.one_time_price)} Website Baseline only if no current, usable review exists. See ${a('/pricing/#after-launch','current plan prices')} and ${a('/pricing/#payments','billing and cancellation terms')}.`)),
  section('before-buying','Ask what will be completed','<p>Ask which site and tasks are covered, what you need to supply, how changes are approved and how completion is checked. Provider fees are separate. A finite review can help when the cause of a problem is still unclear; monthly service is optional.</p>')
 ],
 "/guides/website-audit-checklist/":o=>[
  section('start','Choose one visitor task first',p('Start with a task that matters: identify the right service, understand its boundaries or send an inquiry. Write what you expected and what happened. “The site feels dated” is a useful concern to explore; “a phone visitor cannot find the service boundary before the contact form” is a testable finding.')+p(`Still deciding whether the site needs a project at all? Use ${a('/guides/website-repair-or-redesign/','the repair-or-redesign decision guide')} before expanding the scope.`)+p(`Use the ${a('/assets/guides/website-audit-checklist.csv','audit checklist (CSV)')} to record what you checked, the result, evidence, any fix and the next check. The worksheet starts at “Untested.” Replace that with pass, fail, not applicable or needs access after checking. Keep screenshots and records free of passwords, customer messages and other private information.`)),
  section('checklist','Check the tasks a customer relies on',ol(['Can you tell what the business offers and whether your job fits?','Can you read the important pages and use the menu on a phone and with a keyboard?','Do prices, contact details, service areas and links agree across the site?','Can you send an inquiry and receive a reply? Use the <a href="/guides/contact-form-not-working/">form test</a> for the full procedure.','Ask your developer to check indexing, page titles, speed, accessibility findings and a way to recover the site. Record unavailable access instead of guessing a pass.'])),
  section('priority','Turn a finding into a small correction',p('Explain the practical consequence of each finding. A blocked primary inquiry task is usually more urgent than a minor spacing issue. An unsupported promise may matter even when every automated check passes. Record what is known, what is uncertain and who decides the priority.')+box('An illustrative small agreed fix',p('Finding: a service link leads to an unrelated page. Scope: correct that one destination in the known component. Completion: the link opens the intended page, its label describes the destination and the affected phone/keyboard path works. A full navigation redesign is a different scope.'))+p('Agree the affected area and completion test before editing. Preserve a recoverable version, implement the correction, then repeat the original failing task and check nearby behavior. An automated result is not a substitute for that retest.')),
  section('owned-fixes','An audit finding a business owner can use',box('Illustrative contact-form finding',`<p><strong>Problem:</strong> the form shows success, but the owner cannot find the inquiry.</p><p><strong>Next check:</strong> look for the same controlled test in the form provider’s submission record, then inspect its notification destination.</p><p><strong>Possible fix:</strong> if the record exists and the recipient is an old mailbox, update that recipient with the owner’s approval.</p><p><strong>Finish:</strong> submit one new test, confirm receipt and inbox arrival, then reply to the controlled address. Record anything that remains unverified.</p>`)+p(`This example is hypothetical. The ${a('/assets/buyer-packs/owned-audit-two-fixes','studio’s two-fix record')} shows separate, actual changes to this website. A successful content check does not prove inbox delivery.`)),
  section('access','Use “needs access” when you cannot test',p('Public pages let you inspect copy, links and many layout or keyboard behaviors. Search Console, analytics, form storage, notification logs, account ownership and restore operations may require authorized access. Mark those checks “needs access” with a named owner and next step; do not turn a missing account into a pass or a guessed diagnosis.')+p('A live form test can create a record or send a notification. Agree the test destination and made-up test details before submitting, then distinguish the browser confirmation, stored record and actual delivery. Recovery tests need a safe environment and an agreed rollback procedure.')+p('Real users, assistive technology and physical devices can expose problems a scanner misses. If a task needs specialist investigation, record the boundary and commission the appropriate review instead of promising that a general website audit covers it.')),
  section('finish','Finish with a dated record and the next decision',ul(['Link the original finding and its evidence date.','State the approved fix and the exact changed page or component.','Record the retest method, result, environment and unresolved limitation.','Name the owner of the remaining issue and the next decision.','Keep the accepted scope and paid handoff materials together.'])+guideReviewChoices(o)+p(`For search-only questions, see ${a('/services/seo/','the SEO scope')}. For a larger redesign, prepare ${a('/guides/website-redesign-brief/','a clear project brief')}.`))
 ],
 "/guides/website-repair-or-redesign/":o=>[
  section('start','Begin with the failure, not the age of the site',p('An older website does not automatically need replacing, and a recent one can still make a customer’s next step difficult. Start with the task that is failing: understand the service, check its boundaries, find the right information or make an inquiry. Write down what should happen and what actually happens before choosing a new design.')+p('For a Buffalo or Erie County service business, that task may include checking an actual delivery area, a booking requirement or which jobs the business accepts. Those facts can reveal a small content gap or a larger change in the service. A new town name or a different visual style, by itself, does not establish the need for another page or a rebuild.')+p(`This is the decision before the project. If you need help documenting the failure, use the ${a('/guides/website-audit-checklist/','audit checklist')}; if a redesign is already justified, move to the ${a('/guides/website-redesign-brief/','redesign brief')}.`)),
  section('keep','Keep what already does the job',p('Keep the current site when its important visitor tasks work, its content matches the business and the ownership and operating arrangements are sound. A clear, maintainable site does not need a new project simply because another design is fashionable.')+p('Record what is worth retaining: accurate service copy, useful URLs, licensed images, recognizable identity, working forms and client-owned accounts. Also identify who can edit, export and recover the site. If those answers are missing, mark them as unresolved; do not assume that either a patch or a rebuild removes the risk.')+p('No new project is a valid decision. Keep an identified next review trigger, such as a changed service, a recurring visitor problem or an editing need the current setup cannot support.')),
  section('contained','Choose a small fix when the boundary is known',p('A correction is a useful candidate when the affected component is known, the platform and access are supported, a recoverable version exists and the completion test is specific. Correcting an approved label or retaining an inquiry choice may fit; an unknown failure across several external tools needs diagnosis first.')+ul(['Name the page or component that changes and what stays useful.','Check the actual stack, delegated permissions and any provider dependency before agreeing the job.','Describe how the original failing task will be retested, including nearby behavior.','Keep any remaining issue and its owner visible instead of calling the whole site fixed.'])+p('Source-code delivery does not imply arbitrary WordPress repairs, emergency recovery or security incident work. Existing-site work is accepted only after a fit and access review.')),
  section('owned','Two small repairs to try before a rebuild',box('Illustrative examples',`<ol><li><strong>A broken inquiry route.</strong> A garden-care page sends every button to the home page. Point the estimate button to the correct form, preserve the selected service and check the phone and keyboard path.</li><li><strong>An unclear offer.</strong> A repair service mixes included work and exclusions in one list. Separate them so a customer can tell whether the job fits before asking for a quote.</li></ol>`)+p(`Both examples assume the existing site and access support a small change. For an actual studio-owned implementation record, see the ${a('/assets/buyer-packs/owned-audit-two-fixes','two-fix example')}; it does not report client outcomes.`)),
  section('rework','When broader changes or a rebuild make sense',p('Rework can make sense when the existing system remains suitable but its content or page structure no longer explains the business. A rebuild becomes a candidate when agreed requirements cannot be met sensibly in that system. Establish which constraint is real before selecting a new platform; a visual preference and an operational limit are different reasons for change.')+box('Hypothetical scenario — not a client project',p('A service business now needs several distinct service journeys and frequent publishing by a nontechnical editor. Its current one-page static setup has no editing workflow that meets those requirements. First check whether supported changes to the current setup could provide the needed structure and editing. If they cannot, scope a rebuild with retained content, useful URLs, account ownership and migration checks. This scenario does not imply a quoted cost, saving or completion date.'))+p('Changing the platform creates work of its own: content transfer, redirects where needed, form and tool checks, editing training and a recovery route. Include those responsibilities in the comparison; a new design does not automatically complete them.')),
  section('compare','Compare the approved scope and the risk left behind',p('Ask each proposed approach to answer the same question: what visitor task will work at acceptance, which assets and accounts remain useful, what must change and what is still unresolved? Compare the affected pages, provider costs, required inputs and retest. The smallest useful change is the one supported by that evidence, not necessarily the smallest quoted line item.')+guideReviewChoices(o)+p(`Use the ${a('/guides/website-project-cost/','budget guide')} for cost components rather than a guessed local repair rate. Actual dates depend on ready inputs, access, reviews, tool fit and capacity; the proposal records the agreed schedule.`)),
  section('worksheet','Make the decision visible before commissioning work',p(`Complete the ${a('/assets/guides/website-repair-or-redesign-worksheet.csv','repair-or-redesign decision worksheet')}. Its six columns record the problem, evidence, content and accounts to keep, platform and access, a small fix with its checks, and your decision. One fictional example shows how to fill it in; use the blank row for your own website.`)+p('Choose one next step: keep the site and record a review trigger; agree a small correction; diagnose a wider unknown; or prepare a rework/rebuild brief. If the necessary access or facts are unavailable, leave the decision open and name the input needed. This is a decision record, not an automated recommendation.'))
 ]
};

export function guideContentSections(path,offers){
 return formatGuideSections(guideContent[path]?.(offers)||[]);
}
